import type { GeospatialCamera, SceneContext } from "@babylonjs/lite";
import { flyGeospatialCameraToAsync } from "@babylonjs/lite";

export interface Place {
  yaw: number;
  pitch: number;
  radius: number;
  center: { x: number; y: number; z: number };
}

const EPSILON = 0.001;

function wrapToPi(value: number): number {
  const twoPi = Math.PI * 2;
  let v = (value + Math.PI) % twoPi;
  if (v < 0) v += twoPi;
  return v - Math.PI;
}

function near(a: number, b: number): boolean {
  return Math.abs(a - b) <= EPSILON;
}

function atPlace(camera: GeospatialCamera, place: Place): boolean {
  return (
    Math.abs(wrapToPi(camera.yaw - place.yaw)) <= EPSILON &&
    near(camera.pitch, place.pitch) &&
    near(camera.radius, place.radius) &&
    near(camera.center.x, place.center.x) &&
    near(camera.center.y, place.center.y) &&
    near(camera.center.z, place.center.z)
  );
}

export function flyToPlace(
  camera: GeospatialCamera,
  scene: SceneContext,
  place: Place,
  durationMs: number
): Promise<boolean> {
  const ms = Number.isFinite(durationMs) ? Math.max(0, durationMs) : 1000;
