    yaw: place.yaw,
    pitch: place.pitch,
    radius: place.radius,
    center: { x: place.center.x, y: place.center.y, z: place.center.z },
    durationMs: ms,
  };
  return flyGeospatialCameraToAsync(camera, scene, options)
    .then(() => atPlace(camera, place))
    .catch(() => false);
}
